import pymupdf, json, glob, os
data = {}
for f in sorted(glob.glob("bp2_current/*.pdf")) + sorted(glob.glob("bp3_current/*.pdf")):
    sid = os.path.basename(f)[11:-4].replace("_","-")
    d = pymupdf.open(f)
    rec = {"file": f, "layers": [o["name"] for o in d.get_ocgs().values()], "pages": []}
    for p in d:
        rec["pages"].append(p.get_text())
        rec.setdefault("annots", [])
        for a in p.annots() or []:
            r = a.rect
            rec["annots"].append({
                "id": a.info.get("id",""), "content": a.info.get("content",""),
                "author": a.info.get("title",""), "date": a.info.get("creationDate",""),
                "mod": a.info.get("modDate",""), "subject": a.info.get("subject",""),
                "w_in": round((r.x1-r.x0)/72.0,2), "h_in": round((r.y1-r.y0)/72.0,2),
                "area_in2": round((r.x1-r.x0)*(r.y1-r.y0)/5184.0,2),
                "stroke": [round(c,3) for c in (a.colors.get("stroke") or [])],
            })
    data[sid] = rec
with open("/tmp/sheets_all.json","w") as fh: json.dump(data, fh, indent=1)
print("sheets:", len(data))
# summary of annotations
from collections import Counter
c = Counter()
for sid, r in data.items():
    for a in r.get("annots", []):
        c[a["id"]] += 1
print("markup ids:", len(c))
for sid in sorted(data):
    if data[sid].get("annots"):
        print(sid, [(a["id"], a["author"], a["date"][2:8], a["subject"], a["stroke"]) for a in data[sid]["annots"]])
